const where = prompt('Куда едешь? Налево, направо или прямо?', '').toLowerCase();

switch (where) {
  case 'налево':
    console.log('Быть тебе женатым');
    break;
  case 'прямо':
    console.log('Живым не бывать');
    break;
  case 'направо':
    console.log('Быть тебе богатым');
    break;
}
